/**
 * Minimal in-process job queue: enqueue, drain, retry with backoff. Jobs never run inside a request.
 */
import { createLogger } from "@/lib/logger";
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp } from "@/types/common";

export type QueuedJob = {
  id: string;
  kind: JobKind;
  runAt: IsoTimestamp;
  attempts: number;
  payload: Readonly<Record<string, unknown>>;
};

export type JobKind =
  | "digest-email"
  | "overdue-issues"
  | "webhook-delivery"
  | "usage-rollup"
  | "search-reindex"
  | "cleanup-archived"
  | "trial-expiry";

/** Attempts after which a job is dropped rather than retried again. */
const MAX_ATTEMPTS = 5;

/** How many jobs `drain()` takes in one pass when no limit is given. */
const DEFAULT_DRAIN = 25;

const logger = createLogger("job-queue");

/**
 * The queue lives in module scope: Taskflow runs one server process and the
 * scheduler is started from `instrumentation.ts`, so there is no second
 * consumer to coordinate with. Swapping this for a real broker means
 * reimplementing these four functions and nothing else.
 */
const pending: QueuedJob[] = [];

/** Idempotent on `id`: re-enqueuing a job keeps the earlier `runAt`. */
export function enqueue(job: QueuedJob): void {
  if (pending.some((queued) => queued.id === job.id)) return;
  pending.push(job);
}

/**
 * Runs everything that is due, oldest first. A handler that throws is put back
 * with an exponential delay until `MAX_ATTEMPTS`, then dropped with a log line
 * — an infinitely retrying job is worse than a lost one.
 */
export async function drain(limit: number = DEFAULT_DRAIN): Promise<number> {
  const now = new Date().toISOString();
  const due = pending
    .filter((job) => job.runAt <= now)
    .sort((a, b) => (a.runAt < b.runAt ? -1 : 1))
    .slice(0, Math.max(0, limit));

  let completed = 0;

  for (const job of due) {
    remove(job.id);

    try {
      await runHandler(job);
      completed += 1;
    } catch (error) {
      const attempts = job.attempts + 1;

      if (attempts >= MAX_ATTEMPTS) {
        logger.error("job dropped after max attempts", {
          id: job.id,
          kind: job.kind,
          attempts,
        });
        continue;
      }

      pending.push({
        ...job,
        attempts,
        runAt: toIsoTimestamp(new Date(Date.now() + backoffMs(attempts))),
      });

      logger.warn("job retry scheduled", {
        id: job.id,
        kind: job.kind,
        attempts,
        reason: error instanceof Error ? error.message : String(error),
      });
    }
  }

  return completed;
}

export function pendingCount(): number {
  return pending.length;
}

/** Test hook: empties the queue. Never call this from application code. */
export function resetQueue(): void {
  pending.length = 0;
}

/** 1s, 2s, 4s, 8s … capped at one minute. */
function backoffMs(attempts: number): number {
  return Math.min(60_000, 2 ** (attempts - 1) * 1_000);
}

function remove(id: string): void {
  const at = pending.findIndex((job) => job.id === id);
  if (at >= 0) pending.splice(at, 1);
}

/**
 * Dispatches one queued job to its runner. The imports are dynamic so the
 * queue module stays free of a cycle: every job module imports this one to
 * enqueue follow-up work.
 */
async function runHandler(job: QueuedJob): Promise<void> {
  const now = new Date();

  switch (job.kind) {
    case "digest-email": {
      const { runDigestEmailJob } = await import("./digest-email-job");
      await runDigestEmailJob(now);
      return;
    }
    case "overdue-issues": {
      const { runOverdueIssueJob } = await import("./overdue-issue-job");
      await runOverdueIssueJob(now);
      return;
    }
    case "webhook-delivery": {
      const { runWebhookDeliveryJob } = await import("./webhook-delivery-job");
      await runWebhookDeliveryJob(now);
      return;
    }
    case "usage-rollup": {
      const { runUsageRollupJob } = await import("./usage-rollup-job");
      await runUsageRollupJob(now);
      return;
    }
    case "search-reindex": {
      const { runSearchReindexJob } = await import("./search-reindex-job");
      const orgId = job.payload.orgId;
      if (typeof orgId !== "string") return;
      await runSearchReindexJob(orgId as Parameters<typeof runSearchReindexJob>[0]);
      return;
    }
    case "cleanup-archived": {
      const { runCleanupArchivedJob } = await import("./cleanup-archived-job");
      await runCleanupArchivedJob(now);
      return;
    }
    case "trial-expiry": {
      const { runTrialExpiryJob } = await import("./trial-expiry-job");
      await runTrialExpiryJob(now);
      return;
    }
  }
}
/**
 * Renders react-email templates and 'sends' them by writing the draft to the log. No network egress.
 */
import { createLogger } from "@/lib/logger";

export type OutgoingEmail = {
  to: string;
  subject: string;
  html: string;
  text: string;
};

export type RenderedEmail = { subject: string; html: string; text: string };

export type EmailTemplate =
  | "invite"
  | "digest"
  | "mention"
  | "invoice"
  | "welcome"
  | "password-reset"
  | "overdue";

const logger = createLogger("email-service");

/** Subject lines per template; the props fill in the bracketed parts. */
const SUBJECTS: Readonly<Record<EmailTemplate, string>> = {
  invite: "You have been invited to a Taskflow workspace",
  digest: "Your Taskflow digest",
  mention: "You were mentioned in Taskflow",
  invoice: "Your Taskflow invoice",
  welcome: "Welcome to Taskflow",
  "password-reset": "Reset your Taskflow password",
  overdue: "You have overdue issues",
};

/**
 * "Sends" a message. Taskflow has no outbound mail transport by design — the
 * corpus must build and run offline — so delivery means writing the draft to
 * the structured log, where the dev tools tab surfaces it.
 */
export async function sendEmail(message: OutgoingEmail): Promise<void> {
  logger.info("email.sent", {
    to: message.to,
    subject: message.subject,
    bytes: message.html.length,
  });
}

/**
 * Renders a template to both an HTML and a plain-text body. The text half is
 * derived from the HTML rather than written twice, so the two can never drift.
 */
export async function renderEmail(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): Promise<RenderedEmail> {
  const subject = subjectFor(template, props);
  const html = renderBody(template, props);

  return { subject, html, text: toPlainText(html) };
}

function subjectFor(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): string {
  const base = SUBJECTS[template];
  const orgName = props.orgName;
  return typeof orgName === "string" ? `${base} — ${orgName}` : base;
}

function renderBody(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): string {
  const rows = Object.entries(props)
    .filter(([, value]) => value !== null && value !== undefined)
    .map(
      ([key, value]) =>
        `<tr><td>${escapeHtml(key)}</td><td>${escapeHtml(String(value))}</td></tr>`,
    )
    .join("");

  return [
    `<html><body><h1>${escapeHtml(SUBJECTS[template])}</h1>`,
    `<table>${rows}</table>`,
    "</body></html>",
  ].join("");
}

function toPlainText(html: string): string {
  return html
    .replace(/<\/(?:tr|h1|p|div)>/g, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/[ \t]+/g, " ")
    .replace(/\n\s+/g, "\n")
    .trim();
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}
/**
 * Renders a react-email component to the `{ subject, html, text }` triple
 * `EmailService` sends.
 *
 * `EmailTemplate` is the closed vocabulary of templates; this module is the
 * only place that maps a name to a component and to a subject line, so
 * adding a template means touching exactly one switch in each direction.
 */
import { render } from "@react-email/components";
import { createElement, type ReactElement } from "react";
import { SITE_CONFIG } from "@/config/site";
import type {
  EmailTemplate,
  RenderedEmail,
} from "@/server/services/email-service";
import { DigestEmail, type DigestEmailProps } from "./digest-email";
import { InviteEmail, type InviteEmailProps } from "./invite-email";
import { InvoiceEmail, type InvoiceEmailProps } from "./invoice-email";
import { MentionEmail, type MentionEmailProps } from "./mention-email";
import { OverdueEmail, type OverdueEmailProps } from "./overdue-email";
import {
  PasswordResetEmail,
  type PasswordResetEmailProps,
} from "./password-reset-email";
import { WelcomeEmail, type WelcomeEmailProps } from "./welcome-email";

type Props = Readonly<Record<string, unknown>>;

/** Reads a string prop defensively — templates are fed loosely typed payloads. */
function str(props: Props, key: string, fallback = ""): string {
  const value = props[key];
  return typeof value === "string" && value !== "" ? value : fallback;
}

function count(props: Props, key: string): number {
  const value = props[key];
  return Array.isArray(value) ? value.length : 0;
}

function elementFor(template: EmailTemplate, props: Props): ReactElement {
  switch (template) {
    case "invite":
      return createElement(InviteEmail, props as unknown as InviteEmailProps);
    case "digest":
      return createElement(DigestEmail, props as unknown as DigestEmailProps);
    case "mention":
      return createElement(MentionEmail, props as unknown as MentionEmailProps);
    case "invoice":
      return createElement(InvoiceEmail, props as unknown as InvoiceEmailProps);
    case "welcome":
      return createElement(WelcomeEmail, props as unknown as WelcomeEmailProps);
    case "password-reset":
      return createElement(
        PasswordResetEmail,
        props as unknown as PasswordResetEmailProps,
      );
    case "overdue":
      return createElement(OverdueEmail, props as unknown as OverdueEmailProps);
  }
}

/** The subject line for a template, derived from the same props as the body. */
export function subjectFor(template: EmailTemplate, props: Props): string {
  switch (template) {
    case "invite":
      return `${str(props, "inviterName", "Someone")} invited you to ${str(
        props,
        "orgName",
        SITE_CONFIG.name,
      )}`;
    case "digest": {
      const total = count(props, "entries");
      return `Your ${str(props, "orgName", SITE_CONFIG.name)} digest — ${total} update${
        total === 1 ? "" : "s"
      }`;
    }
    case "mention":
      return `${str(props, "actorName", "Someone")} mentioned you on "${str(
        props,
        "issueTitle",
        "an issue",
      )}"`;
    case "invoice":
      return `Invoice ${str(props, "invoiceNumber", "")} for ${str(
        props,
        "orgName",
        SITE_CONFIG.name,
      )}`.replace(/\s+/g, " ");
    case "welcome":
      return `Welcome to ${SITE_CONFIG.name}`;
    case "password-reset":
      return `Reset your ${SITE_CONFIG.name} password`;
    case "overdue": {
      const total = count(props, "issues");
      return `${total} overdue issue${total === 1 ? "" : "s"} in ${SITE_CONFIG.name}`;
    }
  }
}

/** Renders both the HTML and the plain-text alternative in one pass. */
export async function renderTemplate(
  template: EmailTemplate,
  props: Props,
): Promise<RenderedEmail> {
  const element = elementFor(template, props);
  const [html, text] = await Promise.all([
    render(element),
    render(element, { plainText: true }),
  ]);

  return { subject: subjectFor(template, props), html, text };
}

